use std::fs

fn main() {
    let limit: int = 200000
    let mut comp: Vec<bool> = [false; 200001]
    let mut i: int = 2
    while i * i <= limit {
        if !comp[i] {
            let mut j: int = i * i
            while j <= limit {
                comp[j] = true
                j += i
            }
        }
        i += 1
    }
    let mut cnt: Vec<int> = [0; 200001]
    let mut last: Vec<int> = [0; 200001]
    let mut c: int = 0
    let mut l: int = 0
    let mut k: int = 2
    while k <= limit {
        if !comp[k] {
            c += 1
            l = k
        }
        cnt[k] = c
        last[k] = l
        k += 1
    }
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut toks: Vec<string> = []
    for t in text.split_whitespace() {
        toks.push(t.to_string())
    }
    if toks.len() == 0 {
        return
    }
    let t: int = toks[0].parse::<int>().unwrap_or(0)
    let mut out: Vec<string> = []
    let mut q: int = 1
    while q <= t && q < toks.len() {
        let n: int = toks[q].parse::<int>().unwrap_or(0)
        if n < 2 {
            out.push("0 none")
        } else {
            out.push("${cnt[n]} ${last[n]}")
        }
        q += 1
    }
    println(out.join("\n"))
}

